// PropertyVault service worker (Stage 5, commercial-launch execution plan, WORKLOG.md this date).
// Hand-written, not generated by a build-time tool (e.g. next-pwa/Workbox) -- next-pwa has known
// incompatibilities with the App Router on recent Next.js major versions, and this app's actual
// offline/caching needs are small enough that a plain, auditable service worker is a better fit
// than pulling in a build-plugin dependency for it. Bump CACHE_VERSION on any change to the
// caching strategy below -- the activate handler evicts every cache not matching it.
const CACHE_VERSION = 'propertyvault-v1';
const OFFLINE_URL = '/offline';

// Precached at install so the offline fallback is available even on a visitor's very first
// load (before anything else has been cached by use).
const PRECACHE_URLS = [OFFLINE_URL];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_VERSION).then((cache) => cache.addAll(PRECACHE_URLS)).then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE_VERSION).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return; // never intercept writes -- POST/PATCH/DELETE always hit the network directly

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // never cache/intercept cross-origin requests (Supabase, vendor APIs)

  // API routes: network-only, deliberately never cached. This app's data is financial/tenant/
  // owner-sensitive and changes on every write from potentially another device -- a cached API
  // response could show a stale balance or, worse, a stale "who has access" answer. Offline means
  // "the write/read fails," never "a silently stale answer."
  if (url.pathname.startsWith('/api/')) {
    return;
  }

  // Navigations (HTML page loads): network-first, falling back to the offline page only when the
  // network is genuinely unreachable -- never serve a cached/stale page for a signed-in user's
  // dashboard, which is exactly the kind of state that must always be live.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() => caches.match(OFFLINE_URL).then((cached) => cached ?? Response.error())),
    );
    return;
  }

  // Static, content-hashed build assets (Next.js fingerprints every /_next/static/ file by
  // content, so a cached copy can never go stale under a given URL) and this app's own small
  // public/ asset set: cache-first, falling back to network and caching the result for next time.
  if (url.pathname.startsWith('/_next/static/') || url.pathname.startsWith('/icons/') || request.destination === 'image' || request.destination === 'font') {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ??
          fetch(request).then((response) => {
            if (response.ok) {
              const clone = response.clone();
              caches.open(CACHE_VERSION).then((cache) => cache.put(request, clone));
            }
            return response;
          }),
      ),
    );
  }
  // Everything else: default browser behaviour (no respondWith call) -- not every GET needs an
  // opinionated strategy, and an unhandled fetch event falls through to the network exactly as if
  // no service worker were installed at all.
});
